// GERADO — NAO EDITAR A MAO.
// Fonte Inter (subset Latin-1 + pontuacao), embutida como data URI para o PDF
// de marca da Forio (@react-pdf/renderer, Font.register). Data URI evita
// dependencia de filesystem/rede em runtime serverless — a fonte viaja com o
// codigo. Cobertura = WinAnsi (mesma do Helvetica atual), sem regressao de
// glifos. Pesos: 400 (Regular) e 500 (Medium) — o manual da Forio usa 400/500,
// sem bold sintetico.
//
// Regenerar (releases oficiais rsms/inter, GitHub):
//   curl -L -o Inter.zip https://github.com/rsms/inter/releases/download/v4.1/Inter-4.1.zip
//   unzip -j Inter.zip extras/ttf/Inter-Regular.ttf extras/ttf/Inter-Medium.ttf
//   pyftsubset Inter-Regular.ttf --unicodes="U+0020-007E,U+00A0-00FF,U+2013-2014,U+2018-2019,U+201C-201D,U+2026,U+20AC,U+2122,U+2248" --layout-features=kern,liga --no-hinting --desubroutinize --output-file=Inter-Regular.sub.ttf
//   (idem para Medium) e reencodar em base64.
/* eslint-disable */

export const INTER_REGULAR_TTF =
  "data:font/ttf;base64,";

export const INTER_MEDIUM_TTF =
  "data:font/ttf;base64,";

